<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use DI\ContainerBuilder;
use Slim\Psr7\Response;
use Slim\Psr7\Factory\ServerRequestFactory;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Oidc\Client\Domain\ClientData;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepName;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\Oidc\Authentication\Application\SessionManager;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\OidcStepRouter;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\AuthorizeHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\ConsentForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\ScopesConsentForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\DelegateForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\LoginForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\NewMfaForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\NewPassForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\RecoverPassForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\UseMfaForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\RegisterUserForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\OidcCookieManager;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\OidcResponseBuilder;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcUrlBuilder;
use Civi\Lughauth\Features\Oidc\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\Oidc\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Features\Oidc\Key\Domain\Gateway\TokenSigner;
use Civi\Lughauth\Features\Oidc\Session\Domain\Gateway\TemporalKeysGateway;

/**
 * Integration tests for {@see AuthorizeHtml} step delegation.
 */
final class AuthorizeHtmlIntegrationUnitTest extends TestCase
{
    private array $serverBackup = [];

    #[Override]
    protected function setUp(): void
    {
        $this->serverBackup = $_SERVER;
        $_SERVER['HTTPS'] = 'on';
        $_SERVER['HTTP_HOST'] = 'example.com';
        $_SERVER['SCRIPT_NAME'] = '/index.php';
    }

    #[Override]
    protected function tearDown(): void
    {
        $_SERVER = $this->serverBackup;
    }

    /**
     * Verifies authorize delegates render to the routed form.
     */
    public function testAuthorizeDelegatesToStepRouter(): void
    {
        $request = (new ServerRequestFactory())
            ->createServerRequest('GET', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
                'step' => StepName::CONSENT->value,
                'code_challenge' => 'E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM',
                'code_challenge_method' => 'S256',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);

        $clients = $this->createMock(ClientStoreGateway::class);
        $clients->expects($this->once())
            ->method('publicClientData')
            ->with('client-123', 'tenant1', 'https://client.example/callback', 'openid')
            ->willReturn(new ClientData('client-123', ['code'], true));
        $sessions = $this->createMock(SessionManager::class);
        $sessions->expects($this->once())
            ->method('loadSession')
            ->willReturn(null);

        $consentForm = $this->createMock(ConsentForm::class);
        $consentForm->expects($this->once())
            ->method('render')
            ->willReturn(StepResult::render(new Response(), new ChallengesState()));

        $router = new OidcStepRouter(
            $consentForm,
            $this->createMock(ScopesConsentForm::class),
            $this->createMock(LoginForm::class),
            $this->createMock(NewMfaForm::class),
            $this->createMock(NewPassForm::class),
            $this->createMock(UseMfaForm::class),
            $this->createMock(RecoverPassForm::class),
            $this->createMock(DelegateForm::class),
            $this->createMock(RegisterUserForm::class)
        );

        $cookies = $this->createMock(OidcCookieManager::class);
        $cookies->expects($this->once())
            ->method('clearSession')
            ->willReturn(new Response());

        $authorize = new AuthorizeHtml(
            $context,
            $clients,
            $sessions,
            $this->createMock(AuthenticateUser::class),
            $this->createMock(HtmlSecurer::class),
            $this->createMock(DecorateHtml::class),
            $this->createMock(OidcResponseBuilder::class),
            $cookies,
            new OidcUrlBuilder($context),
            $router
        );

        $response = $authorize->authorize($request, new Response(), ['tenant' => 'tenant1']);

        $this->assertInstanceOf(ResponseInterface::class, $response);
    }

    /**
     * Verifies formAuthorize proceeds through the step router.
     */
    public function testFormAuthorizeProceedsWithCsid(): void
    {
        $request = (new ServerRequestFactory())
            ->createServerRequest('POST', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
                'code_challenge' => 'E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM',
                'code_challenge_method' => 'S256',
            ])
            ->withParsedBody([
                'csid' => 'signed-csid'
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);

        $clients = $this->createMock(ClientStoreGateway::class);
        $clients->expects($this->once())
            ->method('publicClientData')
            ->with('client-123', 'tenant1', 'https://client.example/callback', 'openid')
            ->willReturn(new ClientData('client-123', ['code'], true));

        $securer = $this->createMock(HtmlSecurer::class);
        $securer->expects($this->once())
            ->method('verifyToken')
            ->with('signed-csid')
            ->willReturn('csid-123');

        $authResponse = new PublicLoginAuthResponse(
            tenant: 'tenant1',
            authData: [
                'aud' => ['client-123'],
                'azp' => 'client-123',
                'iss' => 'https://example.com/oauth/openid/tenant1',
                'sub' => 'user-1',
                'name' => 'User 1',
                'email' => 'user@example.com',
                'tenant' => 'tenant1',
                'tenant-name' => 'Tenant 1',
                'scope' => 'openid',
                'roles' => [],
                'groups' => []
            ],
            authExpiration: new \DateInterval('PT10M'),
            idData: [],
            idExpiration: new \DateInterval('PT10M'),
            sessionId: 'sess-123',
            sessionExpiration: new \DateInterval('PT10M')
        );

        $loginForm = $this->createMock(LoginForm::class);
        $loginForm->expects($this->once())
            ->method('authenticate')
            ->willReturn(StepResult::proceed($authResponse, new ChallengesState()));

        $temporals = $this->createMock(TemporalKeysGateway::class);
        $temporals->expects($this->once())
            ->method('registerTemporalAuthCode')
            ->willReturn('temp-code');

        $consentForm = $this->createMock(ConsentForm::class);
        $scopesConsentForm = $this->createMock(ScopesConsentForm::class);
        $newMfaForm = $this->createMock(NewMfaForm::class);
        $newPassForm = $this->createMock(NewPassForm::class);
        $useMfaForm = $this->createMock(UseMfaForm::class);
        $recoverForm = $this->createMock(RecoverPassForm::class);
        $delegateForm = $this->createMock(DelegateForm::class);
        $registerForm = $this->createMock(RegisterUserForm::class);

        $router = new OidcStepRouter(
            $consentForm,
            $scopesConsentForm,
            $loginForm,
            $newMfaForm,
            $newPassForm,
            $useMfaForm,
            $recoverForm,
            $delegateForm,
            $registerForm
        );

        $cookies = new OidcCookieManager($context, $this->createMock(TokenSigner::class));
        $responseBuilder = new OidcResponseBuilder(
            $this->createMock(TokenSigner::class),
            $temporals,
            $cookies
        );
        $urlBuilder = new OidcUrlBuilder($context);

        $authorize = new AuthorizeHtml(
            $context,
            $clients,
            $this->createMock(SessionManager::class),
            $this->createMock(AuthenticateUser::class),
            $securer,
            $this->createMock(DecorateHtml::class),
            $responseBuilder,
            $cookies,
            $urlBuilder,
            $router
        );

        $response = $authorize->formAuthorize($request, new Response(), ['tenant' => 'tenant1']);

        $this->assertSame(302, $response->getStatusCode());
        $this->assertStringContainsString('code=temp-code', $response->getHeaderLine('Location'));
        $this->assertStringContainsString('state=state-xyz', $response->getHeaderLine('Location'));
    }
}
